mapper.select:
select t.inout_id,t.inout_id inoutId,t.machine_id,t.machine_id machineId,t.machine_code,t.machine_code
machineCode,t.open_type_cd,t.open_type_cd openTypeCd,t.user_name userName,t.user_id userId,t.tel,
t.status_cd,t.status_cd statusCd,t.state,t.community_id,t.community_id communityId,t.create_time createTime,
lm.machine_name machineName
from lock_inout t
left join lock_machine lm on t.machine_id = lm.machine_id
where 1 =1 and lm.status_cd = '0'

    and t.inout_id= #{inoutId}


    and t.machine_id= #{machineId}


    and t.machine_code like concat('%', #{machineCode}, '%')


    and t.open_type_cd= #{openTypeCd}


    and t.user_name= #{userName}


    and t.user_id= #{userId}


    and t.tel= #{tel}


    and t.status_cd= #{statusCd}


    and t.state= #{state}


    and t.community_id= #{communityId}

order by t.create_time desc

    limit #{page}, #{row}

